#!/usr/bin/env python3
"""prototype: independent neighbourhood-quotient r, cross-family, agent-0221"""
import itertools, hashlib
import numpy as np

def batcher_pairs(n):
    m = 1
    while m < n: m *= 2
    pairs = []
    p = 1
    while p < m:
        k = p
        while k >= 1:
            j = k % p
            while j <= m - 1 - k:
                for i in range(0, min(k, m - j - k)):
                    if (i + j) // (2 * p) == (i + j + k) // (2 * p):
                        a, b = i + j, i + j + k
                        if a < b: pairs.append((a, b))
                j += 2 * k
            k //= 2
        p *= 2
    return [(a, b) for (a, b) in pairs if b < n], m

def oet_pairs(n):
    out = []
    for t in range(n):
        for i in range(t % 2, n - 1, 2):
            out.append((i, i + 1))
    return out

def three_smooth_below(n):
    s = set()
    a = 1
    while a < n:
        b = a
        while b < n:
            s.add(b); b *= 3
        a *= 2
    return sorted(s)

def pratt_pairs(n):
    out = []
    for g in reversed(three_smooth_below(n)):
        for i in range(0, n - g):
            out.append((i, i + g))
    return out

def insertion_pairs(n):
    out = []
    for i in range(1, n):
        for j in range(i - 1, -1, -1):
            out.append((j, j + 1))
    return out

def bitonic_directed(m):
    """iterative bitonic: list of (a,b,asc) with a<b; asc=True -> min to a."""
    out = []
    k = 2
    while k <= m:
        j = k // 2
        while j >= 1:
            for i in range(m):
                l = i ^ j
                if l > i:
                    asc = (i & k) == 0
                    out.append((i, l, asc))
            j //= 2
        k *= 2
    return out

def untangle(m, directed):
    """Knuth standard-form conversion: relabel channels after each reversed comparator.
    Returns all-ascending pair list of same length and same layer structure."""
    sigma = list(range(m))       # logical channel -> physical channel
    out = []
    for (x, y, asc) in directed:
        i, j = sigma[x], sigma[y]
        lo, hi = (i, j) if i < j else (j, i)
        out.append((lo, hi))
        # comparator (lo,hi) puts min at lo. we need min at logical x.
        min_at_logical = x if ((asc and i < j) or ((not asc) and i > j)) else y
        if min_at_logical != x:
            # relabel: swap sigma[x], sigma[y] so that x receives the min channel
            sigma[x], sigma[y] = sigma[y], sigma[x]
    return out

def pack_layers(n, pairs):
    ready = [0] * n
    layers = []
    for (a, b) in pairs:
        t = max(ready[a], ready[b])
        while len(layers) <= t: layers.append([])
        layers[t].append((a, b))
        ready[a] = ready[b] = t + 1
    return layers

# ------------------------------------------------------------- bit-parallel evaluation
def init_channels(n):
    N = 1 << n
    idx = np.arange(N, dtype=np.uint32)
    return [((idx >> c) & 1).astype(np.uint8) for c in range(n)]

def run(ch, pairs):
    c = [x.copy() for x in ch]
    for (a, b) in pairs:
        x, y = c[a], c[b]
        c[a] = x & y
        c[b] = x | y
    return c

def values(n, c):
    v = np.zeros(len(c[0]), dtype=np.uint32)
    for k in range(n):
        v |= c[k].astype(np.uint32) << k
    return v

def sorts_all(n, pairs):
    c = run(init_channels(n), pairs)
    v = values(n, c)
    # sorted iff 0^k 1^(n-k): value is (2^n - 2^k) pattern -> v+1 is power of two shifted
    ok = set(int(x) for x in np.unique(v))
    good = {((1 << n) - 1) ^ ((1 << k) - 1) for k in range(n + 1)}
    return ok <= good, len(ok)

def unsorted_outputs(n, pairs):
    c = run(init_channels(n), pairs)
    v = np.unique(values(n, c))
    good = {((1 << n) - 1) ^ ((1 << k) - 1) for k in range(n + 1)}
    return sum(1 for x in v if int(x) not in good), len(v)

def multiset_key(n, ch, pairs):
    c = run(ch, pairs)
    v = values(n, c)
    bc = np.bincount(v, minlength=(1 << n)).astype(np.uint32)
    return hashlib.blake2b(bc.tobytes(), digest_size=16).digest()

def r_of(n, prefix):
    allp = list(itertools.combinations(range(n), 2))
    ch = init_channels(n)
    seen = set()
    T = 0
    variants = set()
    for p in range(len(prefix)):
        for c in allp:
            q = list(prefix); q[p] = c
            variants.add(tuple(q))
    variants.add(tuple(prefix))
    T = len(variants)
    for q in variants:
        seen.add(multiset_key(n, ch, q))
    return T, len(seen), len(seen) / T

def row(n, name, pairs):
    good, nout = sorts_all(n, pairs)
    assert good, ("does not sort", name, n)
    L = pack_layers(n, pairs)
    flat = [c for lay in L[:-1] for c in lay]
    U, R = unsorted_outputs(n, flat)
    T, M, r = r_of(n, flat)
    return dict(n=n, family=name, size=len(pairs), depth=len(L), prefix_len=len(flat),
                U=U, reach=R, prefixes=T, multisets=M, r=round(r, 6),
                reduction=round(1 / r, 4), sorts_all=True)

if __name__ == "__main__":
    import sys, json, time
    # anchor 1: n=5 batcher prefix + 31/64
    pb, m = batcher_pairs(5)
    L = pack_layers(5, pb)
    flat = [c for lay in L[:-1] for c in lay]
    print("n5 prefix", flat)
    print("n5 r", r_of(5, flat))
    for n in (10, 12):
        for name, gen in (("batcher", lambda n: batcher_pairs(n)[0]),
                          ("oet", oet_pairs), ("pratt", pratt_pairs),
                          ("insertion", insertion_pairs)):
            t = time.time()
            print(json.dumps(row(n, name, gen(n))), "%.1fs" % (time.time() - t))
        # bitonic
        mm = 1
        while mm < n: mm *= 2
        d = bitonic_directed(mm)
        std = untangle(mm, d)
        okfull = sorts_all(mm, std)
        print("bitonic m=%d untangled sorts:" % mm, okfull)
        rest = [(a, b) for (a, b) in std if b < n]
        print("bitonic restricted sorts:", sorts_all(n, rest))

